#!/usr/bin/env bash
set -euo pipefail

target=${1:-preview}
files=(app.ts app.tsx)

build() {
  printf 'Building %s\n' "$target"
  for file in "${files[@]}"; do
    printf '  %s\n' "$file"
  done
}

build

#!/usr/bin/env bash

function greet() {
  printf 'Hello, %s!\n' "$1"
}

function report {
  local count=${1:-3}
  printf 'Processed %s files\n' "$count"
}

greet Virgo
report 5

#!/bin/sh
source_dir=${1:-assets}
target_dir=${2:-public}

mkdir -p "$target_dir"
for file in "$source_dir"/*; do
  if [ -f "$file" ]; then
    cp "$file" "$target_dir/"
  fi
done
